import { Toast as ToastPrimitive } from "@shardsui/svelte";

export type {
  ToastManagerAddOptions,
  ToastManagerPositionerProps,
  ToastObject,
} from "@shardsui/svelte";
export type { AnchoredToastProviderProps } from "./anchored-toast-provider.svelte";
export {
  default as AnchoredProvider,
  default as AnchoredToastProvider,
} from "./anchored-toast-provider.svelte";
export type {
  ToastData,
  ToastPortalContainer,
  ToastPortalContainerRef,
  ToastPortalProps,
  ToastPortalRef,
  ToastPortalRefCallback,
  ToastPortalRefObject,
  ToastPosition,
  ToastSwipeDirection,
} from "./toast.types.js";
export {
  getToastManager,
  ToastManager as Manager,
  ToastManager,
  type ToastManagerContext,
  type ToastManagerPromiseOptions,
  type ToastManagerUpdateOptions,
} from "./toast-manager.js";
export { anchoredToastManager, toastManager } from "./toast-managers.js";
export type { ToastProviderProps } from "./toast-provider.svelte";
export { default as Provider, default as ToastProvider } from "./toast-provider.svelte";
export { ToastPrimitive };

import type {
  ToastManagerUpdateOptions as PrimitiveToastManagerUpdateOptions,
  ToastManagerAddOptions,
  ToastObject,
} from "@shardsui/svelte";
import { Toast as ToastPrimitive } from "@shardsui/svelte";

export type ToastManagerUpdateOptions<Data extends object = object> = {
  [Key in keyof PrimitiveToastManagerUpdateOptions<Data>]?:
    | PrimitiveToastManagerUpdateOptions<Data>[Key]
    | undefined;
};

export type ToastManagerPromiseOptions<Value, Data extends object = object> = {
  loading: string | ToastManagerUpdateOptions<Data>;
  success:
    | string
    | ToastManagerUpdateOptions<Data>
    | ((result: Value) => string | ToastManagerUpdateOptions<Data>);
  error:
    | string
    | ToastManagerUpdateOptions<Data>
    | ((error: unknown) => string | ToastManagerUpdateOptions<Data>);
};

type ToastMutationTarget<Data extends object> = {
  add(options: ToastManagerAddOptions<Data>): string;
  update(id: string, updates: ToastManagerUpdateOptions<Data>): void;
};

export type ToastManagerContext<Data extends object = object> = ToastMutationTarget<Data> & {
  readonly toasts: ToastObject<Data>[];
  close(id?: string): void;
  promise<Value, T extends Data = Data>(
    promiseValue: Promise<Value>,
    options: ToastManagerPromiseOptions<Value, T>,
  ): Promise<Value>;
};

function toUpdateOptions<Data extends object>(
  options: string | ToastManagerUpdateOptions<Data>,
): ToastManagerUpdateOptions<Data> {
  return typeof options === "string" ? { description: options } : options;
}

function resolvePromiseOptions<Value, Data extends object>(
  options:
    | string
    | ToastManagerUpdateOptions<Data>
    | ((result: Value) => string | ToastManagerUpdateOptions<Data>),
  result: Value,
): ToastManagerUpdateOptions<Data> {
  return toUpdateOptions(options instanceof Function ? options(result) : options);
}

function asPrimitiveUpdate<Data extends object>(
  updates: ToastManagerUpdateOptions<Data>,
): PrimitiveToastManagerUpdateOptions<Data> {
  return updates as PrimitiveToastManagerUpdateOptions<Data>;
}

function handlePromise<Value, Data extends object>(
  target: ToastMutationTarget<Data>,
  promiseValue: Promise<Value>,
  options: ToastManagerPromiseOptions<Value, Data>,
): Promise<Value> {
  const loadingOptions = toUpdateOptions(options.loading);
  const id = target.add({ ...loadingOptions, type: "loading" } as ToastManagerAddOptions<Data>);

  return promiseValue
    .then((result) => {
      const successOptions = resolvePromiseOptions(options.success, result);
      target.update(id, {
        ...successOptions,
        timeout: successOptions.timeout,
        type: successOptions.type ?? "success",
      });
      return result;
    })
    .catch((error: unknown) => {
      const errorOptions = resolvePromiseOptions(options.error, error);
      target.update(id, {
        ...errorOptions,
        timeout: errorOptions.timeout,
        type: errorOptions.type ?? "error",
      });
      return Promise.reject(error);
    });
}

export class ToastManager<Data extends object = object> extends ToastPrimitive.Manager<Data> {
  override promise<Value, T extends Data = Data>(
    promiseValue: Promise<Value>,
    options: ToastManagerPromiseOptions<Value, T>,
  ): Promise<Value> {
    return handlePromise(
      {
        add: (addOptions) => this.add(addOptions),
        update: (id, updates) => this.update(id, asPrimitiveUpdate(updates)),
      },
      promiseValue,
      options,
    );
  }
}

export function getToastManager<Data extends object = object>(): ToastManagerContext<Data> {
  const primitive = ToastPrimitive.getToastManager<Data>();
  const target: ToastMutationTarget<Data> = {
    add: primitive.add,
    update(id, updates) {
      primitive.update(id, asPrimitiveUpdate(updates));
    },
  };

  return {
    get toasts() {
      return primitive.toasts;
    },
    add: target.add,
    close: primitive.close,
    promise: (promiseValue, options) => handlePromise(target, promiseValue, options),
    update: target.update,
  };
}

import type { ToastData } from "./toast.types.js";
import { ToastManager } from "./toast-manager.js";

export const toastManager = new ToastManager<ToastData>();
export const anchoredToastManager = new ToastManager<ToastData>();

import type {
  ToastManager as PrimitiveToastManager,
  Toast as ToastPrimitive,
} from "@shardsui/svelte";
import type { ComponentProps, Snippet } from "svelte";
import type { HTMLAttributes } from "svelte/elements";
import type { ToastManager } from "./toast-manager.js";

export type ToastPosition =
  | "top-left"
  | "top-center"
  | "top-right"
  | "bottom-left"
  | "bottom-center"
  | "bottom-right";

export type ToastSwipeDirection = "up" | "down" | "left" | "right";

export type ToastData = {
  rootProps?: Omit<
    ComponentProps<typeof ToastPrimitive.Root>,
    "children" | "class" | "swipeDirection" | "toast"
  >;
  tooltipStyle?: boolean;
};

type PrimitiveProviderProps = ComponentProps<typeof ToastPrimitive.Provider>;
export type ToastPortalContainerRef = {
  current: HTMLElement | ShadowRoot | null;
};
export type ToastPortalContainer = HTMLElement | ShadowRoot | ToastPortalContainerRef | null;
// biome-ignore lint/suspicious/noConfusingVoidType: Base UI callback refs may return teardown cleanup.
export type ToastPortalRefCallback = (node: HTMLDivElement | null) => void | (() => void);
export type ToastPortalRefObject = {
  current: HTMLDivElement | null;
};
export type ToastPortalRef = ToastPortalRefCallback | ToastPortalRefObject | null;
export type ToastPortalProps = Omit<HTMLAttributes<HTMLDivElement>, "children" | "ref"> & {
  container?: ToastPortalContainer | undefined;
  ref?: ToastPortalRef | undefined;
};

export type ToastProviderProps<Data extends object = ToastData> = Omit<
  PrimitiveProviderProps,
  "children" | "toastManager"
> & {
  children?: Snippet;
  portalProps?: ToastPortalProps;
  position?: ToastPosition;
  toastManager?: ToastManager<Data> | PrimitiveToastManager<Data>;
};

export type AnchoredToastProviderProps<Data extends object = ToastData> = Omit<
  PrimitiveProviderProps,
  "children" | "toastManager"
> & {
  children?: Snippet;
  portalProps?: ToastPortalProps;
  toastManager?: ToastManager<Data> | PrimitiveToastManager<Data>;
};

export function getToastSwipeDirection(position: ToastPosition): ToastSwipeDirection[] {
  const verticalDirection: ToastSwipeDirection = position.startsWith("top") ? "up" : "down";

  if (position.includes("center")) return [verticalDirection];
  if (position.includes("left")) return ["left", verticalDirection];
  return ["right", verticalDirection];
}

export function getToastReplayClass(toast: {
  type?: string;
  updateKey?: number;
}): string | undefined {
  const updateKey = toast.updateKey ?? 0;
  if (updateKey <= 0) return undefined;

  const parity = updateKey % 2 === 0 ? "even" : "odd";
  return toast.type === "error"
    ? `animate-toast-error-${parity}`
    : `animate-toast-success-${parity}`;
}
